"use client"

import React from "react"
import { useRef, useState, useCallback, useEffect } from "react"
import { JSX } from "react/jsx-runtime"

interface MapCanvasProps {
  className?: string
}

interface Transform {
  x: number
  y: number
  scale: number
}

const GRID_SIZE_MILES = 1 // Each grid cell represents 1 mile
const BASE_CELL_SIZE = 100 // Base pixel size for 1 mile at scale 1
const MIN_SCALE = 0.1
const MAX_SCALE = 5
const GRID_EXTENT = 50 // How many miles to render in each direction from center

export function MapCanvas({ className }: MapCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [transform, setTransform] = useState<Transform>({ x: 0, y: 0, scale: 1 })
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 })

  // Update container size on mount and resize
  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        setContainerSize({
          width: containerRef.current.clientWidth,
          height: containerRef.current.clientHeight,
        })
      }
    }
    updateSize()
    window.addEventListener("resize", updateSize)
    return () => window.removeEventListener("resize", updateSize)
  }, [])

  // Handle right-click drag for panning
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (e.button === 2) {
        // Right click
        e.preventDefault()
        setIsDragging(true)
        setDragStart({ x: e.clientX - transform.x, y: e.clientY - transform.y })
      }
    },
    [transform.x, transform.y]
  )

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (isDragging) {
        setTransform((prev) => ({
          ...prev,
          x: e.clientX - dragStart.x,
          y: e.clientY - dragStart.y,
        }))
      }
    },
    [isDragging, dragStart]
  )

  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  // Handle scroll wheel for zooming
  const handleWheel = useCallback(
    (e: React.WheelEvent) => {
      e.preventDefault()

      const rect = containerRef.current?.getBoundingClientRect()
      if (!rect) return

      // Get mouse position relative to container
      const mouseX = e.clientX - rect.left
      const mouseY = e.clientY - rect.top

      // Calculate zoom
      const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1
      const newScale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, transform.scale * zoomFactor))

      // Adjust position to zoom toward mouse cursor
      const scaleRatio = newScale / transform.scale
      const newX = mouseX - (mouseX - transform.x) * scaleRatio
      const newY = mouseY - (mouseY - transform.y) * scaleRatio

      setTransform({
        x: newX,
        y: newY,
        scale: newScale,
      })
    },
    [transform]
  )

  // Prevent context menu on right click
  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault()
  }, [])

  // Calculate visible grid range
  const cellSize = BASE_CELL_SIZE * transform.scale
  const centerX = containerSize.width / 2 + transform.x
  const centerY = containerSize.height / 2 + transform.y

  // Generate grid lines
  const gridLines: JSX.Element[] = []
  const labels: JSX.Element[] = []

  for (let i = -GRID_EXTENT; i <= GRID_EXTENT; i++) {
    const x = centerX + i * cellSize
    const y = centerY + i * cellSize
    const isMajor = i % 5 === 0

    // Vertical lines
    if (x >= -cellSize && x <= containerSize.width + cellSize) {
      gridLines.push(
        <line
          key={`v-${i}`}
          x1={x}
          y1={0}
          x2={x}
          y2={containerSize.height}
          stroke={isMajor ? "var(--map-grid-major)" : "var(--map-grid)"}
          strokeWidth={isMajor ? 1.5 : 0.5}
          opacity={isMajor ? 0.8 : 0.4}
        />
      )

      // X-axis labels (miles from center)
      if (isMajor && transform.scale > 0.3) {
        labels.push(
          <text
            key={`lx-${i}`}
            x={x}
            y={centerY + 16}
            fill="var(--map-label)"
            fontSize={11}
            textAnchor="middle"
            fontFamily="var(--font-mono)"
            opacity={0.7}
          >
            {i !== 0 ? `${i}mi` : "0"}
          </text>
        )
      }
    }

    // Horizontal lines
    if (y >= -cellSize && y <= containerSize.height + cellSize) {
      gridLines.push(
        <line
          key={`h-${i}`}
          x1={0}
          y1={y}
          x2={containerSize.width}
          y2={y}
          stroke={isMajor ? "var(--map-grid-major)" : "var(--map-grid)"}
          strokeWidth={isMajor ? 1.5 : 0.5}
          opacity={isMajor ? 0.8 : 0.4}
        />
      )

      // Y-axis labels (miles from center)
      if (isMajor && i !== 0 && transform.scale > 0.3) {
        labels.push(
          <text
            key={`ly-${i}`}
            x={centerX + 8}
            y={y + 4}
            fill="var(--map-label)"
            fontSize={11}
            textAnchor="start"
            fontFamily="var(--font-mono)"
            opacity={0.7}
          >
            {`${-i}mi`}
          </text>
        )
      }
    }
  }

  // Draw center crosshair
  const crosshairSize = 20

  return (
    <div
      ref={containerRef}
      className={`relative overflow-hidden select-none ${className}`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      onContextMenu={handleContextMenu}
      style={{ cursor: isDragging ? "grabbing" : "default" }}
    >
      <svg width={containerSize.width} height={containerSize.height} className="absolute inset-0">
        {/* Grid lines */}
        {gridLines}

        {/* Center crosshair */}
        <line
          x1={centerX - crosshairSize}
          y1={centerY}
          x2={centerX + crosshairSize}
          y2={centerY}
          stroke="var(--accent)"
          strokeWidth={2}
          opacity={0.8}
        />
        <line
          x1={centerX}
          y1={centerY - crosshairSize}
          x2={centerX}
          y2={centerY + crosshairSize}
          stroke="var(--accent)"
          strokeWidth={2}
          opacity={0.8}
        />

        {/* Center point */}
        <circle cx={centerX} cy={centerY} r={4} fill="var(--accent)" opacity={0.9} />

        {/* Labels */}
        {labels}
      </svg>

      {/* HUD Overlay */}
      <div className="absolute bottom-4 left-4 bg-card/80 backdrop-blur-sm border border-border rounded-lg p-3 font-mono text-sm">
        <div className="text-muted-foreground">
          <span className="text-accent">Zoom:</span> {(transform.scale * 100).toFixed(0)}%
        </div>
        <div className="text-muted-foreground">
          <span className="text-accent">Pan:</span> ({Math.round(-transform.x / cellSize)},{" "}
          {Math.round(transform.y / cellSize)}) mi
        </div>
        <div className="text-muted-foreground mt-1 text-xs opacity-60">
          <span className="text-accent">1 cell</span> = {GRID_SIZE_MILES} mile
        </div>
      </div>

      {/* Controls hint */}
      <div className="absolute top-4 right-4 bg-card/80 backdrop-blur-sm border border-border rounded-lg p-3 text-sm">
        <div className="text-muted-foreground">
          <span className="text-accent font-medium">Right-click + drag</span> to pan
        </div>
        <div className="text-muted-foreground">
          <span className="text-accent font-medium">Scroll</span> to zoom
        </div>
      </div>

      {/* Title */}
      <div className="absolute top-4 left-4">
        <h1 className="text-xl font-semibold text-foreground">
          London Underground <span className="text-accent">Visualiser</span>
        </h1>
        <p className="text-sm text-muted-foreground">Interactive Map Grid</p>
      </div>
    </div>
  )
}
